const FORM_STRINGS={SENDING:"Sending...",DEFAULT:"Send Inquiry",SUCCESS:"Thank you! Your inquiry has been submitted successfully.",CONNECT_ERROR:"Unable to connect. Please try again later.",FIELDS_REQUIRED:"Please fill in all fields.",INVALID_EMAIL:"Please enter a valid email address.",GENERIC_ERROR:"Something went wrong. Please try again."},EMAIL_REGEX=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;function validateInquiryForm({name:e,email:t,whatsapp:n,message:s}){return!e||!t||!n||!s?FORM_STRINGS.FIELDS_REQUIRED:EMAIL_REGEX.test(t)?null:FORM_STRINGS.INVALID_EMAIL}document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("inquiryForm");e&&e.addEventListener("submit",async t=>{t.preventDefault();const n=document.getElementById("submitBtn"),s=document.getElementById("btnText"),r={name:e.name.value.trim(),email:e.email.value.trim(),whatsapp:e.whatsapp.value.trim(),message:e.message.value.trim(),website_url:e.website_url?e.website_url.value:""},a=validateInquiryForm(r);if(a){showToast(a,"error");return}if(confirm("Are you sure you want to send this inquiry?")){n.disabled=!0,s.textContent=FORM_STRINGS.SENDING;try{const i=await(await fetch("../api/submit-inquiry.php",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(r)})).json();i.success?(showToast(FORM_STRINGS.SUCCESS,"success"),e.reset()):showToast(i.error||FORM_STRINGS.GENERIC_ERROR,"error")}catch{showToast(FORM_STRINGS.CONNECT_ERROR,"error")}finally{n.disabled=!1,s.textContent=FORM_STRINGS.DEFAULT}}})});
